JS_COMMON = r'''
(function(){
 const html=document.documentElement, body=document.body;
 const header=document.querySelector('.site-header');
 const saved=localStorage.getItem('apah-theme');
 if(saved==='dark'||(!saved&&window.matchMedia('(prefers-color-scheme: dark)').matches)){body.classList.add('dark');}
 function themeLabel(){return body.classList.contains('dark')?'Dark Theme':'Normal Theme'}
 document.querySelectorAll('[data-theme-toggle]').forEach(b=>{b.setAttribute('aria-label','Switch theme');b.addEventListener('click',()=>{body.classList.toggle('dark');localStorage.setItem('apah-theme',body.classList.contains('dark')?'dark':'light');b.setAttribute('aria-pressed',body.classList.contains('dark')?'true':'false');b.textContent=themeLabel();});b.textContent=themeLabel();b.setAttribute('aria-pressed',body.classList.contains('dark')?'true':'false');});
 const menu=document.querySelector('.mobile-panel'); const mt=document.querySelector('.menu-toggle');
 if(mt&&menu){mt.addEventListener('click',()=>{const open=menu.classList.toggle('open');mt.setAttribute('aria-expanded',open?'true':'false');});}
 const onScroll=()=>header&&header.classList.toggle('scrolled',window.scrollY>12);window.addEventListener('scroll',onScroll,{passive:true});onScroll();
 document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
 document.querySelectorAll('[data-modal-open]').forEach(btn=>btn.addEventListener('click',()=>{const id=btn.getAttribute('data-modal-open');const m=document.getElementById(id);if(m){m.classList.add('open');m.setAttribute('aria-hidden','false');const f=m.querySelector('button,input,textarea,select');f&&f.focus();}}));
 document.querySelectorAll('[data-modal-close]').forEach(btn=>btn.addEventListener('click',()=>{const m=btn.closest('.modal');if(m){m.classList.remove('open');m.setAttribute('aria-hidden','true');}}));
 document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m){m.classList.remove('open');m.setAttribute('aria-hidden','true');}}));
 document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal.open').forEach(m=>{m.classList.remove('open');m.setAttribute('aria-hidden','true');});});
 function setupFilters(){document.querySelectorAll('[data-filter-list]').forEach(list=>{const inputs=document.querySelectorAll('[data-filter-input]');inputs.forEach(i=>i.addEventListener('input',()=>{const q=(i.value||'').toLowerCase();list.querySelectorAll('[data-filter-item]').forEach(card=>card.classList.toggle('hide',q&&!card.textContent.toLowerCase().includes(q)));}));});}
 setupFilters();
 const bot=document.querySelector('.chat-panel'), launch=document.querySelector('.chat-launch'); if(bot&&launch){launch.addEventListener('click',()=>{const open=bot.classList.toggle('open');launch.setAttribute('aria-expanded',open?'true':'false');});}
 async function api(path, options={}){const opts={credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options}; if(['POST','PUT','PATCH','DELETE'].includes((opts.method||'GET').toUpperCase())){try{const r=await fetch('/api/csrf',{credentials:'include'});if(r.ok){const j=await r.json();opts.headers['X-CSRF-Token']=j.token;}}catch(_){}}
 const res=await fetch(path,opts);let data={};try{data=await res.json();}catch(_){} if(!res.ok)throw new Error(data.detail||data.message||'Request failed');return data;}
 window.APAH={api};
 document.querySelectorAll('form[data-api]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const status=form.querySelector('[data-status]');const button=form.querySelector('button[type=submit]');const original=button&&button.textContent;if(status){status.classList.remove('show','error-status');status.textContent='';} if(button){button.disabled=true;button.textContent='Processing…';}
 try{let body; if(form.enctype==='multipart/form-data'){body=new FormData(form); const res=await fetch(form.dataset.api,{method:'POST',body,credentials:'include',headers:{'X-CSRF-Token':(await (await fetch('/api/csrf',{credentials:'include'})).json()).token}}); if(!res.ok)throw new Error((await res.json()).detail||'Request failed'); body=null;} else {body=Object.fromEntries(new FormData(form));await api(form.dataset.api,{method:'POST',body:JSON.stringify(body)});} form.reset();if(status){status.textContent=form.dataset.success||'Thank you. Your request has been received.';status.classList.add('show');status.focus();}}
 catch(err){if(status){status.textContent=err.message||'We could not complete your request. Please try again.';status.classList.add('show','error-status');status.focus();}}
 finally{if(button){button.disabled=false;button.textContent=original;}}}));
})();
'''
