ORG_JSON={"@context":"https://schema.org","@type":"Organization","name":"Africa Power Advisory Holding","url":"/","logo":"/assets/brand/logo.svg"}

def head(lang,title,desc,path):
    other='fr' if lang=='en' else 'en'; otherpath=path.replace('/en/','/fr/') if lang=='en' else path.replace('/fr/','/en/')
    return f'''<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | Africa Power Advisory Holding</title><meta name="description" content="{desc}"><link rel="icon" href="/assets/brand/favicon.svg" type="image/svg+xml"><link rel="alternate icon" href="/assets/brand/favicon.ico" sizes="32x32"><link rel="apple-touch-icon" href="/assets/brand/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest"><meta name="theme-color" content="#071a2b"><link rel="canonical" href="{path}"><link rel="alternate" hreflang="{lang}" href="{path}"><link rel="alternate" hreflang="{other}" href="{otherpath}"><link rel="alternate" hreflang="x-default" href="/fr/"><meta property="og:type" content="website"><meta property="og:title" content="{title} | Africa Power Advisory Holding"><meta property="og:description" content="{desc}"><meta property="og:url" content="{path}"><meta property="og:locale" content="{'en_US' if lang=='en' else 'fr_FR'}"><script type="application/ld+json">{json.dumps(ORG_JSON,ensure_ascii=False)}</script>'''

def header(lang, current):
    n=NAV[lang]
    def a(k,label=None): return f'<a href="{href(lang,k)}" class="{label or k}" aria-current="true">{label or n[k]}</a>' if k==current else f'<a href="{href(lang,k)}" class="{label or k}">{label or n[k]}</a>'
    lang_href=href('fr' if lang=='en' else 'en', current if current in NAV['en'] else 'home')
    lang_text='Passer en français' if lang=='en' else 'Switch to English'
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="container"><div class="nav-row"><a class="brand" href="{href(lang,'home')}" aria-label="Africa Power Advisory Holding home"><img src="/assets/brand/logo.svg" alt="Africa Power Advisory Holding"></a><nav class="nav-links" aria-label="Primary navigation">{a('home')}{a('about')}{a('services')}{a('projects')}{a('insights')}{a('actuality')}{a('careers')}{a('contact')}<div class="nav-tools"><a class="btn btn-secondary" href="{href(lang,'newsletter')}">{n['newsletter']}</a><a href="{lang_href}" lang="{'fr' if lang=='en' else 'en'}" aria-label="{lang_text}">{'FR' if lang=='en' else 'EN'}</a><button type="button" class="icon-btn" data-theme-toggle aria-pressed="false"></button></div></nav><button type="button" class="menu-toggle" aria-label="Open menu" aria-controls="mobile-menu" aria-expanded="false">☰</button></div><div id="mobile-menu" class="mobile-panel"><nav class="mobile-links" aria-label="Mobile navigation">{a('home')}{a('about')}{a('services')}{a('projects')}{a('insights')}{a('actuality')}{a('careers')}{a('contact')}<a href="{href(lang,'newsletter')}">{n['newsletter']}</a><a href="{lang_href}" lang="{'fr' if lang=='en' else 'en'}" aria-label="{lang_text}">{'FR | EN' if lang=='en' else 'EN | FR'}</a><button type="button" data-theme-toggle aria-pressed="false">{n['theme']}</button></nav></div></div></header>'''

def footer(lang):
    n=NAV[lang]
    return f'''<footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="{href(lang,'home')}"><img src="/assets/brand/logo-light.svg" alt="Africa Power Advisory Holding" width="170"></a><p style="margin-top:15px">{t(lang,'Strategic Energy Advisory and Power Solutions for Africa.','Conseil énergétique stratégique et solutions électriques pour l’Afrique.')}</p></div><div><h3>{t(lang,'Explore','Explorer')}</h3><ul><li>{footer_link(lang,'about','about')}</li><li>{footer_link(lang,'services','services')}</li><li>{footer_link(lang,'projects','projects')}</li><li>{footer_link(lang,'insights','insights')}</li><li>{footer_link(lang,'actuality','actuality')}</li><li>{footer_link(lang,'careers','careers')}</li></ul></div><div><h3>{t(lang,'Offices','Bureaux')}</h3><div class="office"><strong>Kinshasa</strong><span>13A, avenue Lufungulo, Ngaliema, Kinshasa, Democratic Republic of the Congo</span></div><div class="office"><strong>Lusaka</strong><span>Makeni 55, Kafue Road, Lusaka, Zambia</span></div></div><div><h3>{t(lang,'Legal','Juridique')}</h3><ul><li>{footer_link(lang,t(lang,'Privacy Policy','Politique de confidentialité'),'privacy')}</li><li>{footer_link(lang,t(lang,'Cookie Policy','Politique de cookies'),'cookie')}</li><li>{footer_link(lang,t(lang,'Terms and Conditions','Conditions générales'),'terms')}</li><li>{footer_link(lang,t(lang,'Consent Management','Gestion du consentement'),'consent')}</li><li>{footer_link(lang,t(lang,'Accessibility Statement','Déclaration d’accessibilité'),'accessibility')}</li><li>{footer_link(lang,t(lang,'Legal Notices','Mentions légales'),'legal')}</li><li>{footer_link(lang,t(lang,'Recruitment Privacy Notice','Confidentialité du recrutement'),'recruitment-privacy')}</li></ul></div></div><div class="footer-bottom"><span>© <span data-year></span> Africa Power Advisory Holding. {t(lang,'All rights reserved.','Tous droits réservés.')}</span><span>{t(lang,'Company information published only when verified.','Les informations de l’entreprise sont publiées uniquement après vérification.')}</span></div></div></footer><button type="button" class="btn btn-primary chat-launch" aria-expanded="false" aria-controls="chat-panel">{t(lang,'Chat','Chat')}</button><section id="chat-panel" class="chat-panel" aria-label="{t(lang,'Visitor chatbot','Chatbot visiteurs')}"><div class="chat-head">{t(lang,'Africa Power Advisory Holding','Africa Power Advisory Holding')}</div><div class="chat-body"><div class="chat-msg agent">{t(lang,'Welcome. Tell us what you need help with, and we will guide you.','Bienvenue. Expliquez-nous votre besoin et nous vous orienterons.')}</div><p class="help">{t(lang,'Please avoid sharing sensitive personal information.','Évitez de partager des données personnelles sensibles.')}</p></div><form class="chat-form" data-api="/api/chat" data-success="{t(lang,'Your request has been received. Our team will follow up through your preferred contact channel.','Votre demande a été reçue. Notre équipe assurera le suivi via votre canal de contact préféré.')}"><input name="name" required aria-label="{t(lang,'Full name','Nom complet')}" placeholder="{t(lang,'Full name','Nom complet')}"><input type="email" name="email" required aria-label="Email" placeholder="Email"><input name="organization" aria-label="{t(lang,'Organization','Organisation')}" placeholder="{t(lang,'Organization','Organisation')}"><select name="service" aria-label="{t(lang,'Service of interest','Service recherché')}"><option value="">{t(lang,'Service of interest','Service recherché')}</option>{''.join(f'<option>{x[1]}</option>' for x in (services_en if lang=='en' else services_fr))}</select><textarea name="context" rows="3" aria-label="{t(lang,'Project context','Contexte du projet')}" placeholder="{t(lang,'Project context','Contexte du projet')}"></textarea><label class="help"><input type="checkbox" name="consent" value="yes" required> {t(lang,'I agree to the processing of the information above for follow-up on my request.','J’accepte le traitement des informations ci-dessus pour le suivi de ma demande.')} <a href="{href(lang,'privacy')}">{t(lang,'Privacy Policy','Politique de confidentialité')}</a>.</label><div data-status role="status" tabindex="-1"></div><button class="btn btn-primary" type="submit">{t(lang,'Send request','Envoyer la demande')}</button></form></section>'''

def footer_link(lang, label, key): return f'<a href="{href(lang,key)}">{label}</a>'

def page_wrap(lang, file_rel, current, title, desc, body, extra_js=''):
    path='/' + file_rel.replace('public/','')
    jsname=Path(file_rel).stem+'.js'; cssname=Path(file_rel).stem+'.css'
    csslang='fr' if lang=='fr' else 'en'; relbase=Path('/'.join(file_rel.split('/')[:-1]))
    # matching files are in assets/css/<lang>/<stem>.css
    return f'''<!doctype html><html lang="{lang}"><head>{head(lang,title,desc,path)}<link rel="stylesheet" href="/assets/css/common.css"><link rel="stylesheet" href="/assets/css/{lang}/{cssname}"></head><body>{header(lang,current)}<main id="main">{body}</main>{footer(lang)}<script type="module" src="/assets/js/{lang}/{jsname}"></script>{extra_js}</body></html>'''

def page_css_js(lang, stem, page_css='', page_js=''):
    d=(PUB/'assets/css'/lang); d.mkdir(parents=True,exist_ok=True)
    d2=(PUB/'assets/js'/lang); d2.mkdir(parents=True,exist_ok=True)
    (d/f'{stem}.css').write_text(page_css)
    (d2/f'{stem}.js').write_text("import '/assets/js/common.js';\n"+page_js)

def service_cards(lang):
    arr=services_en if lang=='en' else services_fr
    prefix='/en/services-industries/services/' if lang=='en' else '/fr/services-et-secteurs/services/'
    return ''.join(f'<article class="card"><div class="icon-box">{i+1:02d}</div><h3>{name}</h3><p>{desc}</p><a class="card-link" href="{prefix}{slug}">{t(lang,"View service","Voir le service")} →</a></article>' for i,(slug,name,desc) in enumerate(arr))

def industry_cards(lang):
    arr=industries_en if lang=='en' else industries_fr
    prefix='/en/services-industries/industries/' if lang=='en' else '/fr/services-et-secteurs/secteurs/'
    return ''.join(f'<article class="card"><div class="icon-box">{i+1:02d}</div><h3>{name}</h3><p>{desc}</p><a class="card-link" href="{prefix}{slug}">{t(lang,"View sector","Voir le secteur")} →</a></article>' for i,(slug,name,desc) in enumerate(arr))

def experts_html(lang):
    cards=''
    for e in experts:
        media=f'<img src="{e["img"]}" alt="Portrait of {e["name"]}, {e["title"]}" width="480" height="600" loading="lazy" decoding="async">' if e['img'] else f'<div class="expert-placeholder" aria-label="{e["name"]}">{e["initials"]}</div>'
        bio=e['bio_en'] if lang=='en' else e['bio_fr']
        cards += f'''<article class="card"><div class="expert-media">{media}</div><span class="pill">{e['spec']}</span><h3>{e['name']}</h3><p><strong>{e['title']}</strong></p><p>{bio}</p><div class="bio-actions"><button class="btn btn-secondary" type="button" data-modal-open="bio-{e['slug']}">{t(lang,'Read Bio','Lire la bio')}</button></div></article>'''
    modals=''.join(f'''<section class="modal" id="bio-{e['slug']}" aria-hidden="true" role="dialog" aria-modal="true" aria-labelledby="bio-title-{e['slug']}"><div class="dialog"><div class="dialog-head"><div><span class="pill">{e['spec']}</span><h2 id="bio-title-{e['slug']}">{e['name']}</h2><p><strong>{e['title']}</strong></p></div><button class="icon-btn" type="button" data-modal-close aria-label="{t(lang,'Close','Fermer')}">×</button></div><p>{e['bio_en'] if lang=='en' else e['bio_fr']}</p><a class="btn btn-primary" href="{href(lang,'contact')}">{t(lang,"Let's Talk Together","Parlons ensemble")}</a></div></section>''' for e in experts)
    return cards+modals

