def add(lang, rel, current, title, desc, body, css='', js=''):
    target=PUB/rel
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(page_wrap(lang,rel,current,title,desc,body))
    page_css_js(lang,target.stem,css,js)
    pages.append('/'+rel)

